<script setup lang="ts">
import { assetVariant, safeUrl, type Block } from '~/lib/site'
import RichText from './RichText'
defineProps<{ blocks: Block[] }>()
const copied = ref('')
async function copy(block: Extract<Block, { type: 'code' }>) { try { await navigator.clipboard.writeText(block.code); copied.value = block.id } catch { copied.value = `${block.id}-error` } }
</script>
<template><div class="content-blocks"><section v-for="block in blocks" :id="`block-${block.id}`" :key="block.id" class="content-block" :class="[`block-${block.type}`, block.type === 'image' ? `align-${block.alignment || 'center'}` : '']"><RichText v-if="block.type === 'richtext' && block.document" :document="block.document" /><PhotoGallery v-else-if="block.type === 'image' && block.assetId" :photos="[{ assetId: block.assetId, alt: block.alt || '', caption: block.caption }]" layout="continuous" /><PhotoGallery v-else-if="block.type === 'gallery'" :photos="block.items || []" :layout="block.layout" /><ContentMedia v-else-if="block.type === 'audio' || block.type === 'video'" :block="block" /><blockquote v-else-if="block.type === 'quote'" class="quote"><p>{{ block.text }}</p><cite v-if="block.attribution"><a v-if="safeUrl(block.sourceUrl)" :href="safeUrl(block.sourceUrl)" rel="noopener noreferrer">{{ block.attribution }}</a><template v-else>{{ block.attribution }}</template></cite></blockquote><div v-else-if="block.type === 'code'" class="code-block"><div class="code-label"><span>{{ block.filename || block.language || '代码' }}</span><button @click="copy(block)">{{ copied === block.id ? '已复制' : (copied === `${block.id}-error` ? '复制失败，请选中文字复制' : '复制') }}</button></div><pre><code>{{ block.code }}</code></pre></div><div v-else-if="block.type === 'file'" class="attachment"><SiteIcon name="file" :size="28" /><div><strong>{{ block.label || '附件' }}</strong><p v-if="block.description" class="small muted">{{ block.description }}</p><span v-if="assetVariant(block.assetId, 'download')?.bytes" class="small muted">{{ (assetVariant(block.assetId, 'download')!.bytes! / 1024 / 1024).toFixed(1) }} MB</span></div><a v-if="assetVariant(block.assetId, 'download')" class="button" :href="assetVariant(block.assetId, 'download')?.url" download>下载<SiteIcon name="download" /></a><span v-else class="muted">附件暂时不可用</span></div></section></div></template>
